Cypress.Commands.add('login', (role) => {
  cy.task('auth:session', role, { log: false }).then((session) => {
    cy.setCookie('sessionid', session, { log: false });
  });
});
Cypress.Commands.add('setLanguage', (language) => {
  cy.request(`/book/?lang=${language}`);
});
Cypress.Commands.add('assertNoBusinessChange', (before) => {
  cy.task('db:snapshot').should('deep.equal', before);
});
Cypress.Commands.add('waitForScroll', () => {
  let previous;
  let lastChange = Date.now();
  // Cypress retries the observation; an animation-frame counter can be
  // throttled in a headless window even after scrolling has already finished.
  cy.window().should((win) => {
    if (win.scrollY !== previous) {
      previous = win.scrollY;
      lastChange = Date.now();
    }
    expect(Date.now() - lastChange, 'scroll position remains stable').to.be.at.least(200);
  });
});
Cypress.Commands.add('assertGuidedStep', (selector) => {
  cy.get(selector).should('be.focused').should(($heading) => {
    const heading = $heading[0];
    const doc = heading.ownerDocument;
    const win = doc.defaultView;
    const rect = heading.getBoundingClientRect();
    const margin = parseFloat(win.getComputedStyle(heading).scrollMarginTop) || 0;
    const padding = parseFloat(win.getComputedStyle(doc.documentElement).scrollPaddingTop) || 0;
    const maximum = Math.max(0, doc.documentElement.scrollHeight - win.innerHeight);
    const target = Math.max(0, Math.min(maximum, win.scrollY + rect.top - margin - padding));
    expect(Math.abs(win.scrollY - target), 'guided scroll reached its CSS destination').to.be.at.most(2);
    expect(rect.top).to.be.at.least(0);
    expect(rect.bottom).to.be.at.most(win.innerHeight);
  });
});
Cypress.Commands.add('chooseFilter', (name, value) => {
  cy.intercept('GET', '/book/?*').as('filterRefresh');
  if (name === 'date') {
    // Calendar replaces the native date select in the enhanced UI.
    cy.get('#date-calendar').then(($calendar) => {
      const button = $calendar.find(`[data-date="${value}"]`);
      if (!button.length || button.prop('disabled')) {
        cy.get('[data-month-step="1"]').click();
      }
    });
    cy.get(`#date-calendar [data-date="${value}"]`).click();
  } else {
    cy.get(`#visit-selection [name="${name}"]`).select(String(value));
  }
  cy.wait('@filterRefresh').its('response.statusCode').should('eq', 200);
  cy.get(`#visit-selection [name="${name}"]`).should('have.value', String(value));
  cy.get('#booking-content').should('not.have.attr', 'aria-busy', 'true');
});

// Do not suppress uncaught exceptions: JavaScript errors fail the audit.
let consoleErrors = [];
Cypress.on('window:before:load', (win) => {
  const original = win.console.error;
  win.console.error = function (...args) {
    consoleErrors.push(args.map(String).join(' '));
    return original.apply(this, args);
  };
});
beforeEach(() => {
  consoleErrors = [];
  // The browser HTTP cache is not reset by testIsolation. Keeping the app script
  // uncacheable lets fallback tests reliably withhold it using cy.intercept.
  cy.intercept({ url: '**/booking/booking.js*', middleware: true }, (req) => {
    req.on('before:response', (res) => { res.headers['cache-control'] = 'no-store'; });
  });
  cy.task('db:reset').as('seed');
});
afterEach(function () {
  cy.task('audit:console', { test: this.currentTest.fullTitle(), errors: consoleErrors });
  cy.then(() => expect(consoleErrors, 'application console.error messages').to.deep.equal([]));
});
